from io import StringIO
import pytest

from isort.core import process
from isort.settings import Config, DEFAULT_CONFIG
from isort.exceptions import ExistingSyntaxErrors, FileSkipComment


def test_process_float_to_top_and_split():
    content = "# isort: off\nimport b\n# isort: on\nimport a\n# isort: split\nimport c\n"
    inp = StringIO(content)
    out = StringIO()
    config = Config(float_to_top=True)
    res = process(inp, out, extension="py", raise_on_skip=True, config=config)
    assert isinstance(res, bool)


def test_process_force_adds_and_skip_file():
    inp = StringIO("")
    out = StringIO()
    config = Config(force_adds=False)
    assert process(inp, out, config=config) is False


def test_process_file_skip_comment_raise():
    inp = StringIO("# isort: skip_file\nimport os\n")
    out = StringIO()
    with pytest.raises(FileSkipComment):
        process(inp, out, raise_on_skip=True)


def test_process_file_skip_comment_no_raise():
    inp = StringIO("# isort: skip_file\nimport os\n")
    out = StringIO()
    res = process(inp, out, raise_on_skip=False)
    assert res is False


def test_process_dont_add_imports_and_on_off():
    inp = StringIO("# isort: dont-add-imports\n# isort: off\n# isort: on\nimport os\n")
    out = StringIO()
    config = Config(add_imports=["sys"])
    process(inp, out, config=config)


def test_process_dont_add_specific_import():
    inp = StringIO("# isort: dont-add-import: sys\nimport os\n")
    out = StringIO()
    config = Config(add_imports=["sys"])
    process(inp, out, config=config)


def test_process_top_comment_and_section_comments():
    inp = StringIO("# Top comment\nx = 1\n# Third-party\nimport os\n")
    out = StringIO()
    config = DEFAULT_CONFIG
    object.__setattr__(config, "_section_comments", ("# Third-party",))
    process(inp, out, config=config)


def test_process_quotes_and_escapes_and_comments():
    inp = StringIO(r'''
"triple \" quote"
'single \' quote'
x = "string with # not a comment"
# comment
import os
''')
    out = StringIO()
    process(inp, out)


def test_process_code_sorting_comments_and_reexports():
    inp = StringIO(
        "# isort: CODE_SORT_START\na = [2, 1]\n# isort: CODE_SORT_END\n"
        "__all__ = ['b', 'a']\n"
    )
    out = StringIO()
    config = Config(sort_reexports=True)
    process(inp, out, config=config)


def test_process_section_comments_end():
    inp = StringIO(
        "# Third-party\nimport os\n# Third-party end\n"
    )
    out = StringIO()
    config = DEFAULT_CONFIG
    object.__setattr__(config, "_section_comments", ("# Third-party",))
    object.__setattr__(config, "_section_comments_end", ("# Third-party end",))
    process(inp, out, config=config)


def test_process_multiline_import_backslash_and_paren_errors():
    inp1 = StringIO("from os import \\\n    path\n")
    out1 = StringIO()
    process(inp1, out1)

    inp2 = StringIO("from os import (\n    path\n")
    out2 = StringIO()
    with pytest.raises(ExistingSyntaxErrors):
        process(inp2, out2)


def test_process_from_without_import():
    inp = StringIO("from os\nimport sys\n")
    out = StringIO()
    process(inp, out)


def test_process_cimports_and_indent_changes():
    inp = StringIO(
        "if True:\n"
        "    cimport a\n"
        "    import b\n"
    )
    out = StringIO()
    process(inp, out)


def test_process_lines_before_imports():
    inp = StringIO("\n\nimport os\n")
    out = StringIO()
    config = Config(lines_before_imports=2)
    process(inp, out, config=config)


def test_process_append_only_and_docstring():
    inp = StringIO('"""Docstring"""\nimport os\n')
    out = StringIO()
    config = Config(append_only=True)
    process(inp, out, config=config)


def test_process_yield_and_raise_multiline():
    inp = StringIO("yield \\\n    foo\nraise \\\n    bar\n")
    out = StringIO()
    process(inp, out)


def test_process_only_modified_verbose():
    inp = StringIO("import b\nimport a\n")
    out = StringIO()
    config = Config(only_modified=True)
    process(inp, out, config=config)
